export const categories = [
  { key: 'commerciale', label: 'Commerciale' },
  { key: 'pubblico', label: 'Pubblico' },
  { key: 'urbano-paesaggio', label: 'Urbano - Paesaggio' },
  { key: 'residenziale', label: 'Residenziale' },
  { key: 'design', label: 'Design' },
] as const

export function getProjectsByCategory(cat: Project['categoria']) {
  return projects.filter(p => p.categoria === cat).sort((a, b) => (b.anno || 0) - (a.anno || 0))
}

export function getProjectBySlug(slug: string) {
  return projects.find(p => p.slug === slug)
}

export function getAllCategories() {
  return categories
}

export function getAllSlugs() {
  return projects.map(p => p.slug)
}
